const items = $input.all();
if (items.length === 0) return [];
const rows = items.map(i => i.json);
const hot = rows.filter(r => r.label === 'Hot');
const warm = rows.filter(r => r.label === 'Warm');

function formatTender(t) {
  const color = t.label === 'Hot' ? '#dc2626' : '#d97706';
  let products = '';
  try { products = JSON.parse(t.recommended_products || '[]').join(', '); } catch(e) { products = String(t.recommended_products || ''); }
  const flags = Array.isArray(t.red_flags) ? t.red_flags : [];
  const flagLine = flags.length ? '<br/><span style="color:#dc2626">Risico: ' + flags.join(', ') + '</span>' : '';
  const routeLine = (t.route_to_market && t.label === 'Hot')
    ? '<br/><strong style="color:#1d4ed8">Route: ' + t.route_to_market + (t.reseller_name ? ' (' + t.reseller_name + ')' : '') + '</strong>' +
      (t.route_first_action ? '<br/><em>Eerste stap: ' + t.route_first_action + '</em>' : '')
    : '';
  const outreachBlock = (t.reseller_outreach_draft && t.label === 'Hot')
    ? '<div style="margin-top:8px;background:#f0f4ff;border-left:3px solid #1d4ed8;padding:8px;font-size:13px;"><strong>Borrador reseller:</strong><br/>' + t.reseller_outreach_draft + '</div>'
    : '';
  return '<div style="margin-bottom:24px;border-left:4px solid ' + color + ';padding-left:12px;">' +
    '<strong>' + (t.naam || '') + '</strong> &mdash; ' + (t.opdrachtgever || '') + '<br/>' +
    '<em>Sluiting: ' + (t.sluiting_datum || 'onbekend') + ' | Score: ' + (t.score || 0) + ' | Label: ' + (t.label || '') + '</em><br/>' +
    '<em>Producten: ' + (products || 'n.v.t.') + ' | Fit: ' + (t.fit_level || 'n.v.t.') + '</em>' + flagLine + routeLine + outreachBlock + '<br/>' +
    (t.executive_summary || '') + '<br/>' +
    (t.recommended_action ? '<strong>Actie: ' + t.recommended_action + '</strong><br/>' : '') +
    '<a href="' + (t.url || '') + '">TenderNed</a></div>';
}

