const item = $input.item.json;
function norm(s) { return (s||'').toLowerCase(); }
const now = new Date();
const bd = {};
bd.d1 = 15;
let d2 = 2;
try {
  const raw = typeof item.raw_json === 'string' ? JSON.parse(item.raw_json) : (item.raw_json || {});
  const v = parseFloat(raw.raamovereenkomstWaarde || raw.opdrachtwaarde || raw.totaleWaarde || 0);
  if (v >= 500000) d2 = 20;
  else if (v >= 200000) d2 = 15;
  else if (v >= 100000) d2 = 10;
  else if (v >= 50000) d2 = 5;
} catch(e) {}
bd.d2 = d2;
const proc = norm(item.procedure);
bd.d3 = proc.includes('openbaar') ? 15 : proc.includes('versneld') ? 13 : proc.includes('niet-openbaar') ? 12 : proc.includes('onderhandeling') ? 10 : proc.includes('mini-competitie') ? 6 : 8;
const buyer = norm(item.opdrachtgever);
const authMap = [[['rijkswaterstaat','ministerie','belastingdienst','cibg','rvo'],'rijksoverheid',15],[['politie'],'politie',14],[['defensie'],'defensie',14],[['provincie'],'provincie',13],[['gemeente amsterdam','gemeente rotterdam','gemeente den haag','gemeente utrecht'],'grote gemeente',13],[['hogeschool','universiteit','mbo'],'onderwijs',12],[['ziekenhuis','umc'],'zorg',11],[['waterschap'],'waterschap',9],[['gemeente'],'gemeente',7]];
let d4 = 5, buyerType = 'overig';
for (const [keys, type, pts] of authMap) { if (keys.some(k => buyer.includes(k))) { d4 = pts; buyerType = type; break; } }
bd.d4 = d4;
const dlWeeks = item.sluiting_datum ? (new Date(item.sluiting_datum) - now) / 6048e5 : null;
bd.d5 = dlWeeks === null ? 5 : dlWeeks >= 6 ? 10 : dlWeeks >= 3 ? 7 : dlWeeks >= 2 ? 4 : dlWeeks >= 0 ? 1 : 0;
const hrs = item.scraped_at ? (now - new Date(item.scraped_at)) / 36e5 : null;
bd.d6 = !hrs || hrs <= 48 ? 5 : hrs <= 120 ? 3 : 1;
bd.d7 = 0;
const rawScore = bd.d1+bd.d2+bd.d3+bd.d4+bd.d5+bd.d6+bd.d7;
const flags = [];
const tn = norm(item.naam);
if (dlWeeks !== null && dlWeeks < 1.5) flags.push('deadline_too_short');
if (dlWeeks !== null && dlWeeks < 0) flags.push('deadline_passed');
if ((tn.includes('verlenging')||tn.includes(' optie '))&&!tn.includes('nieuw')) flags.push('renewal_likely');
const rawLabel = rawScore >= 70 ? 'Hot' : rawScore >= 45 ? 'Warm' : rawScore >= 20 ? 'Cold' : 'Monitor';
const ladder = ['Monitor','Cold','Warm','Hot'];
let label = flags.length > 0 ? (ladder[Math.max(0,ladder.indexOf(rawLabel)-1)]) : rawLabel;
if (flags.includes('deadline_passed')) label = 'Disqualified';
return { json: { ...item, score: rawScore, label, score_breakdown: bd, red_flags: flags, buyer_type_detected: buyerType } };

